W={
'more2-web-css-uutien-1':["ul 1 + li 1 + a 1 + .on 10 = 13.","111 là trọng số của bộ chọn có một id (100) cộng 11; ở đây không có id.","21 sẽ cần hai class; chỉ có một class .on.","12 thiếu: phải cộng cả ba thẻ (3) với .on (10) = 13."],
'more2-web-css-uutien-2':[".a.b.c.d.e = 5 class × 10 = 50.","div ul li a span = 5 thẻ × 1 = 5.","#nav .item a = 100 + 10 + 1 = 111, có id nên lớn nhất.",".nav .item .link a = 3×10 + 1 = 31."],
'more2-web-css-uutien-3':["Quy tắc p{color:red} (trọng số 1) bị style trong thẻ lấn át.","style trực tiếp trong thẻ có mức ưu tiên cao hơn mọi bộ chọn thông thường nên chữ xanh lá.",".x (10) bị style trong thẻ lấn át.","Màu mặc định chỉ dùng khi không có quy tắc nào."],
'more2-web-css-uutien-4':["#a p có trọng số cao hơn nhưng bị !important lấn át.","Không có màu pink nào trong CSS.","Có quy tắc màu nên không phải màu mặc định.","!important thắng cả bộ chọn id nên chữ xanh dương."],
'more2-web-css-uutien-5':["Số thuộc tính không quyết định ưu tiên.","Độ dài bộ chọn không quyết định; trọng số mới quyết định.","Quy tắc viết trước bị ghi đè.","Cùng trọng số thì quy tắc viết sau trong mã nguồn thắng."],
'more2-web-css-uutien-6':["Lề không cộng dồn hai quy tắc; chỉ một quy tắc thắng.","0px là quy tắc .box p, bị p.note ghi đè (viết sau, cùng trọng số 11).","p.note = 1 + 10 = 11 bằng .box p = 10 + 1 = 11; viết sau thắng nên margin 10px.","5px không có trong CSS."],
'more2-web-css-uutien-7':["a:hover = 11 bằng .menu a = 11; viết sau (.menu a) thắng nên không phải blue.","a:hover (1+10 = 11) bằng .menu a (10+1 = 11): viết sau thắng, vậy green.","Đã có quy tắc đặt màu nên không dùng màu mặc định.","a{color:red} có trọng số 1, thấp hơn."],
'more2-web-css-selector-8':["Ba loại tiêu đề không thể đồng thời có ba lớp.","Không có quan hệ lồng nhau; dấu phẩy phân tách.","Dấu phẩy là danh sách các bộ chọn độc lập: áp cho cả h1, h2, h3.","Quan hệ con trực tiếp dùng dấu >."],
'more2-web-css-selector-9':["li + li chọn li đứng LIỀN SAU một li khác (em liền kề).","Con trực tiếp của ul dùng ul > li.","Lồng bên trong li là «li li».","li đầu tiên là li:first-child."],
'more2-web-css-selector-10':["#main > p chỉ chọn p là CON TRỰC TIẾP.","#main p: dấu cách chọn hậu duệ mọi cấp của phần tử id main.",".main p chọn theo class, không phải id.","p #main chọn #main nằm trong p, đảo ngược."],
'more2-web-css-selector-11':["input[type=\"text\"] chọn thẻ input có thuộc tính type bằng text.","Không có thẻ text nằm trong input.","Chọn theo class là .text.","Không chọn theo nội dung văn bản."],
'more2-web-css-selector-12':[".a.b chọn một phần tử, không phải hai phần tử liền kề.","Quan hệ lồng nhau dùng dấu cách.","«hoặc» dùng dấu phẩy .a, .b.","Viết liền (không dấu cách): cùng một phần tử có cả class a và b."],
'more2-web-css-selector-13':["div > p chọn được p con trực tiếp.","p thứ hai nằm trong span nên là cháu, không khớp >.","Chỉ p thứ nhất khớp.","p thứ nhất là con trực tiếp của div; p thứ hai là cháu qua span."],
'more2-web-css-selector-14':["p liền ngay sau h2 là h2 + p.","Bên trong h2 là «h2 p» (hậu duệ).","h2 ~ p: mọi p anh em đứng sau h2, không nhất thiết liền kề.","Đứng trước h2 không thể chọn bằng ~."],
'more2-web-css-pseudo-15':["Lớp giả dùng một dấu hai chấm, không phải hai.","first không phải lớp giả hợp lệ (cần first-child).","a:link: liên kết chưa thăm.","a.visited là class tên visited, không phải lớp giả :visited."],
'more2-web-css-pseudo-16':["before-letter không tồn tại.","::first-letter chọn chữ cái đầu của đoạn.","::first-line chọn dòng đầu.","first-letter-only không tồn tại."],
'more2-web-css-pseudo-17':["Phím Tab tạo :focus, không phải :hover.","hover: khi con trỏ chuột nằm trên phần tử.","Lúc tải xong trang không liên quan đến :hover.","Vừa nhấn chuột là :active."],
'more2-web-css-pseudo-18':["Không phải li đầu tiên toàn trang.","Con đầu tiên bên trong li là «li > :first-child».","li:first-child: li là con đầu tiên của cha nó.","Không liên quan đến hàng hiển thị."],
'more2-web-css-box-19':["330 thiếu: chưa cộng đủ padding hai bên và border.","360 đã cộng margin (nhưng đề không tính margin).","300 + 2×20 + 2×5 = 350.","300 chỉ là width của nội dung."],
'more2-web-css-box-20':["350 là cách tính content-box, đảo ngược.","border-box: nội dung = 300 − 2×20 − 2×5 = 250.","300 là tổng khung, không phải nội dung.","290 mới chỉ trừ một bên padding/border."],
'more2-web-css-box-21':["15 là hiệu hai lề; lề dọc không trừ.","Lề dọc liền kề gộp, lấy lớn hơn: 40px.","65 là cộng dồn; không xảy ra với lề dọc.","25 là lề nhỏ hơn."],
'more2-web-css-box-22':["margin 0 auto: lề trái–phải tự chia đều phần dư nên khối nằm giữa.","Không xoá viền.","Căn trái là margin-right: auto.","Không co khối theo nội dung."],
'more2-web-css-box-23':["padding bốn giá trị theo chiều kim đồng hồ: trên, phải, dưới, trái.","Thứ tự trên-dưới-trái-phải không đúng.","Phải bắt đầu từ trên.","Phải bắt đầu từ trên, không phải trái."],
'more2-web-css-box-24':["Giá trị đầu là trên–dưới, giá trị sau là trái–phải; đảo ngược.","Hai giá trị: trên/dưới 10px, trái/phải 20px.","Hai giá trị áp cho cả hai cặp phía.","Không tính trung bình."],
'more2-web-css-box-25':["Inline vẫn nhận màu nền.","Phần tử inline bỏ qua width, height và margin dọc.","Chiếm hết dòng là block.","Inline không nhận mọi thuộc tính như block."],
'more2-web-css-khung-26':["flex là kiểu bố cục, vẫn hiển thị.","block là hiển thị khối.","hidden không phải giá trị của display (visibility: hidden mới có).","display: none loại hẳn khỏi bố cục."],
'more2-web-css-khung-27':["Anh em liền trước không phải mốc.","Viewport là mốc của fixed (hoặc khi không có tổ tiên định vị).","Vị trí gốc của chính nó là relative.","absolute: tổ tiên gần nhất có position khác static."],
'more2-web-css-khung-28':["fixed đứng yên so với khung nhìn khi cuộn.","Cuộn theo trang là static/relative/absolute.","fixed vẫn hiển thị trên trang, chỉ ra khỏi luồng.","Theo cha là absolute (cha có position)."],
'more2-web-css-khung-29':["row: trục chính là ngang nên justify-content căn ngang.","Chiều dọc là trục phụ (align-items).","Thứ tự mục là thuộc tính order.","Cỡ chữ không liên quan."],
'more2-web-css-khung-30':["column: trục chính là dọc nên đây không phải align-items.","Trục chính dọc → trục phụ ngang; align-items căn ngang.","Vẫn có tác dụng.","Không phụ thuộc mục cuối."],
'more2-web-css-khung-31':["flex-flow: none không phải giá trị hợp lệ để xuống dòng.","overflow không có giá trị wrap.","align-wrap không tồn tại.","flex-wrap: wrap cho phép xuống dòng."],
'more2-web-css-khung-32':["Từ 600px trở lên là min-width.","Ảnh nền không liên quan đến media query.","max-width: 600px: khung nhìn rộng tối đa 600px.","Số từ không liên quan."],
'more2-web-css-khung-33':["16px là 1rem.","2px không đúng đơn vị.","18px không tính được từ 16px và 2.","2rem = 2 × 16px = 32px."],
'more2-web-css-khung-34':["24 = 20 × 1,2 chưa đúng.","1,5px không đúng đơn vị em.","1,5em = 1,5 × 20 = 30px.","35 không phải kết quả của 20 × 1,5."],
'more2-web-css-khung-35':["static là kiểu định vị.","inline-block cho các khối đứng cạnh nhau mà vẫn nhận width/height.","none ẩn phần tử.","float: none là không float."],
'more2-web-css-ke-thua-36':["color được kế thừa từ phần tử cha.","padding không kế thừa.","border không kế thừa.","margin không kế thừa."],
'more2-web-css-ke-thua-37':["Màu đỏ vẫn còn vì quy tắc sau không đặt lại color.","Chữ đỏ, không đen.","Quy tắc sau chỉ ghi đè text-align → left; color đỏ giữ nguyên.","text-align đã bị ghi đè thành left."],
'more2-web-css-nhung-38':["Style từng trang phải viết lại ở mọi trang.","Tệp .css ngoài dùng chung nhiều trang, sửa một nơi đổi tất cả.","Style trong thẻ chỉ cho một phần tử.","Chú thích không có tác dụng định dạng."],
'more2-web-css-nhung-39':["title không chứa link.","Sau </html> là ngoài tài liệu.","Cuối body vẫn được nhưng quy ước đặt link CSS ở head.","link nhúng CSS đặt trong head."],
'more2-web-html-bang-40':["ol: ordered list, có thứ tự.","ul không thứ tự.","dl là danh sách mô tả.","li là mục."],
'more2-web-html-bang-41':["Không có thuộc tính merge.","rowspan gộp hàng.","width đặt độ rộng.","colspan gộp các ô cùng hàng."],
'more2-web-html-bang-42':["Ô rowspan chiếm 1 ô của hàng 2 nên chưa đủ.","0 sẽ làm thiếu 2 cột.","3 sẽ thừa một ô.","3 cột − 1 ô bị rowspan chiếm = 2 td."],
'more2-web-html-bang-43':["caption đặt tiêu đề cho bảng.","thead là nhóm hàng tiêu đề.","title là tiêu đề trang.","header không phải thẻ bảng."],
'more2-web-html-media-44':["title chỉ là chú thích khi rê chuột.","name không phải thuộc tính thay thế.","alt: văn bản thay thế.","src là đường dẫn ảnh."],
'more2-web-html-media-45':["iframe nhúng trang khác trong khung.","frame đã lỗi thời.","embed nhúng nội dung khác, không đặc trưng cho nhúng trang.","object tương tự, không phải câu trả lời chuẩn."],
'more2-web-html-media-46':["Nhiều source để trình duyệt chọn định dạng phù hợp.","Không giới hạn dung lượng.","Phụ đề dùng track.","Ảnh bìa là poster."],
'more2-web-html-media-47':["Tắt tiếng là muted.","Lặp là loop.","controls hiện thanh điều khiển.","Tự phát là autoplay."],
'more2-web-html-lienket-48':["Liên kết dùng href, không phải src.","# phải đứng trước id.","href=\"#muc2\" là neo trong trang.","id gán ở phần tử đích, không dùng cho liên kết."],
'more2-web-html-lienket-49':["_blank là giá trị của target, không phải href.","rel=newtab không có.","open không phải thuộc tính của a.","target=\"_blank\" mở tab mới."],
'more2-web-html-bieumau-50':["Chọn nhiều đáp án là checkbox.","Gửi dữ liệu là nút submit.","Tiêu đề tab là title.","label gắn nhãn cho ô nhập (for trùng id), nháy nhãn chọn ô."],
'more2-web-html-bieumau-51':["value là giá trị gửi của từng nút, mỗi nút khác nhau.","id phải duy nhất.","Cùng name thành một nhóm chỉ chọn một.","label không tạo nhóm."],
'more2-web-html-bieumau-52':["disabled không sửa được và không gửi giá trị.","hidden không phải thuộc tính ô nhập này.","readonly: không sửa được nhưng vẫn gửi.","required: bắt buộc nhập."],
'more2-web-html-bieumau-53':["required: bắt buộc nhập trước khi gửi.","Chỉ nhập số là type=number.","Ẩn ô là type=hidden hoặc display none.","Điền sẵn là value."],
'more2-web-html-cautruc-54':["title hiện tên trang trên tab.","head chứa thông tin về trang.","meta là thông tin trang.","body chứa nội dung hiển thị."],
'more2-web-html-cautruc-55':["id duy nhất để định danh đúng một phần tử.","Trang không bị hỏng, chỉ không đúng chuẩn.","Trình duyệt vẫn mở trang.","CSS vẫn áp dụng; chỉ hành vi định danh sai."],
}
